def list_to_tree(lst):
    if not lst or lst[0] is None:
        return None
    root = TreeNode(lst[0])
    queue = [root]
    i = 1
    while queue and i < len(lst):
        curr = queue.pop(0)
        if i < len(lst) and lst[i] is not None:
            curr.left = TreeNode(lst[i])
            queue.append(curr.left)
        i += 1
        if i < len(lst) and lst[i] is not None:
            curr.right = TreeNode(lst[i])
            queue.append(curr.right)
        i += 1
    return root

def generate(rng, n):
    vals1 = [rng.randint(-100, 100) if rng.random() > 0.3 else None for _ in range(n)]
    vals2 = list(vals1)
    if vals2 and vals2[0] is not None and rng.random() > 0.5:
        vals2[0] += 1
    return [list_to_tree(vals1), list_to_tree(vals2)]

def generate_worst(rng, n):
    vals = [rng.randint(-100, 100) for _ in range(n)]
    return [list_to_tree(vals), list_to_tree(vals)]

